// axil_timer: 32-bit down-counting timer, one-shot and periodic modes, level
// interrupt, behind an AXI4-Lite subordinate port.
// Implements interface_spec.md following microarchitecture.md.
module axil_timer #(
    parameter integer ADDR_WIDTH = 4
) (
    input  wire                  aclk,
    input  wire                  aresetn,

    input  wire [ADDR_WIDTH-1:0] s_axil_awaddr,
    input  wire                  s_axil_awvalid,
    output wire                  s_axil_awready,

    input  wire [31:0]           s_axil_wdata,
    input  wire [3:0]            s_axil_wstrb,
    input  wire                  s_axil_wvalid,
    output wire                  s_axil_wready,

    output wire [1:0]            s_axil_bresp,
    output wire                  s_axil_bvalid,
    input  wire                  s_axil_bready,

    input  wire [ADDR_WIDTH-1:0] s_axil_araddr,
    input  wire                  s_axil_arvalid,
    output wire                  s_axil_arready,

    output wire [31:0]           s_axil_rdata,
    output wire [1:0]            s_axil_rresp,
    output wire                  s_axil_rvalid,
    input  wire                  s_axil_rready,

    output wire                  irq
);

    localparam [1:0] RESP_OKAY   = 2'b00;
    localparam [1:0] RESP_SLVERR = 2'b10;

    localparam [1:0] IDX_CTRL   = 2'd0;
    localparam [1:0] IDX_LOAD   = 2'd1;
    localparam [1:0] IDX_COUNT  = 2'd2;
    localparam [1:0] IDX_STATUS = 2'd3;

    // ------------------------------------------------------------------
    // State
    // ------------------------------------------------------------------
    reg                  aw_held_q, aw_held_d;
    reg [ADDR_WIDTH-1:0] aw_addr_q, aw_addr_d;
    reg                  w_held_q,  w_held_d;
    reg [31:0]           w_data_q,  w_data_d;
    reg [3:0]            w_strb_q,  w_strb_d;
    reg                  bvalid_q,  bvalid_d;
    reg [1:0]            bresp_q,   bresp_d;

    reg                  rvalid_q,  rvalid_d;
    reg [31:0]           rdata_q,   rdata_d;
    reg [1:0]            rresp_q,   rresp_d;

    reg                  en_q,      en_d;
    reg                  ie_q,      ie_d;
    reg                  mode_q,    mode_d;
    reg                  expired_q, expired_d;
    reg [31:0]           load_q,    load_d;
    reg [31:0]           count_q,   count_d;

    // ------------------------------------------------------------------
    // Channel outputs
    // ------------------------------------------------------------------
    assign s_axil_awready = !aw_held_q && !bvalid_q;
    assign s_axil_wready  = !w_held_q && !bvalid_q;
    assign s_axil_bvalid  = bvalid_q;
    assign s_axil_bresp   = bresp_q;
    assign s_axil_arready = !rvalid_q;
    assign s_axil_rvalid  = rvalid_q;
    assign s_axil_rdata   = rdata_q;
    assign s_axil_rresp   = rresp_q;

    assign irq = expired_q && ie_q;

    // ------------------------------------------------------------------
    // Write path decode
    // ------------------------------------------------------------------
    wire aw_hs    = s_axil_awvalid && s_axil_awready;
    wire w_hs     = s_axil_wvalid && s_axil_wready;
    wire do_write = (aw_held_q || aw_hs) && (w_held_q || w_hs);

    wire [ADDR_WIDTH-1:0] wr_addr = aw_held_q ? aw_addr_q : s_axil_awaddr;
    wire [31:0]           wr_data = w_held_q  ? w_data_q  : s_axil_wdata;
    wire [3:0]            wr_strb = w_held_q  ? w_strb_q  : s_axil_wstrb;

    wire       wr_mapped = (wr_addr[1:0] == 2'b00) &&
                           ((wr_addr >> 4) == {ADDR_WIDTH{1'b0}});
    wire [1:0] wr_idx    = wr_addr[3:2];
    wire       wr_ok     = wr_mapped && (wr_idx != IDX_COUNT);

    wire ctrl_we    = do_write && wr_mapped && (wr_idx == IDX_CTRL) && wr_strb[0];
    wire load_we    = do_write && wr_mapped && (wr_idx == IDX_LOAD);
    wire status_clr = do_write && wr_mapped && (wr_idx == IDX_STATUS) &&
                      wr_strb[0] && wr_data[0];

    wire [31:0] wr_mask = {{8{wr_strb[3]}}, {8{wr_strb[2]}},
                           {8{wr_strb[1]}}, {8{wr_strb[0]}}};

    // ------------------------------------------------------------------
    // Read path decode
    // ------------------------------------------------------------------
    wire       ar_hs     = s_axil_arvalid && s_axil_arready;
    wire       rd_mapped = (s_axil_araddr[1:0] == 2'b00) &&
                           ((s_axil_araddr >> 4) == {ADDR_WIDTH{1'b0}});
    wire [1:0] rd_idx    = s_axil_araddr[3:2];

    reg [31:0] rd_value;
    always @* begin
        rd_value = 32'd0;
        if (rd_mapped) begin
            case (rd_idx)
                IDX_CTRL:   rd_value = {29'd0, mode_q, ie_q, en_q};
                IDX_LOAD:   rd_value = load_q;
                IDX_COUNT:  rd_value = count_q;
                IDX_STATUS: rd_value = {31'd0, expired_q};
                default:    rd_value = 32'd0;
            endcase
        end
    end

    // ------------------------------------------------------------------
    // Channel next state
    // ------------------------------------------------------------------
    always @* begin
        aw_held_d = aw_held_q;
        aw_addr_d = aw_addr_q;
        w_held_d  = w_held_q;
        w_data_d  = w_data_q;
        w_strb_d  = w_strb_q;
        bvalid_d  = bvalid_q;
        bresp_d   = bresp_q;
        rvalid_d  = rvalid_q;
        rdata_d   = rdata_q;
        rresp_d   = rresp_q;

        // Write response handshake
        if (bvalid_q && s_axil_bready) begin
            bvalid_d = 1'b0;
        end

        // Capture arriving halves
        if (aw_hs) begin
            aw_addr_d = s_axil_awaddr;
        end
        if (w_hs) begin
            w_data_d = s_axil_wdata;
            w_strb_d = s_axil_wstrb;
        end

        if (do_write) begin
            aw_held_d = 1'b0;
            w_held_d  = 1'b0;
            bvalid_d  = 1'b1;
            bresp_d   = wr_ok ? RESP_OKAY : RESP_SLVERR;
        end else begin
            if (aw_hs) begin
                aw_held_d = 1'b1;
            end
            if (w_hs) begin
                w_held_d = 1'b1;
            end
        end

        // Read channel
        if (rvalid_q && s_axil_rready) begin
            rvalid_d = 1'b0;
        end
        if (ar_hs) begin
            rvalid_d = 1'b1;
            rdata_d  = rd_value;
            rresp_d  = rd_mapped ? RESP_OKAY : RESP_SLVERR;
        end
    end

    // ------------------------------------------------------------------
    // Timer next state (order gives the specified priorities)
    // ------------------------------------------------------------------
    wire count_end = en_q && (count_q[31:1] == 31'd0);

    always @* begin
        en_d      = en_q;
        ie_d      = ie_q;
        mode_d    = mode_q;
        expired_d = expired_q;
        load_d    = load_q;
        count_d   = count_q;

        // 1. Count step
        if (en_q) begin
            if (count_end) begin
                if (mode_q) begin
                    count_d = load_q;
                end else begin
                    count_d = 32'd0;
                    en_d    = 1'b0;
                end
            end else begin
                count_d = count_q - 32'd1;
            end
        end

        // 2. Expired: clear, then set (a count end beats a clear)
        if (status_clr) begin
            expired_d = 1'b0;
        end
        if (count_end) begin
            expired_d = 1'b1;
        end

        // 3. CTRL write wins for en and count
        if (ctrl_we) begin
            ie_d   = wr_data[1];
            mode_d = wr_data[2];
            if (wr_data[0]) begin
                en_d    = 1'b1;
                count_d = load_q;
            end else begin
                en_d = 1'b0;
            end
        end

        // 4. LOAD byte merge
        if (load_we) begin
            load_d = (load_q & ~wr_mask) | (wr_data & wr_mask);
        end
    end

    // ------------------------------------------------------------------
    // Registers: synchronous active-low reset, then q <= d
    // ------------------------------------------------------------------
    always @(posedge aclk) begin
        if (!aresetn) begin
            aw_held_q <= 1'b0;
            aw_addr_q <= {ADDR_WIDTH{1'b0}};
            w_held_q  <= 1'b0;
            w_data_q  <= 32'd0;
            w_strb_q  <= 4'd0;
            bvalid_q  <= 1'b0;
            bresp_q   <= RESP_OKAY;
            rvalid_q  <= 1'b0;
            rdata_q   <= 32'd0;
            rresp_q   <= RESP_OKAY;
            en_q      <= 1'b0;
            ie_q      <= 1'b0;
            mode_q    <= 1'b0;
            expired_q <= 1'b0;
            load_q    <= 32'd0;
            count_q   <= 32'd0;
        end else begin
            aw_held_q <= aw_held_d;
            aw_addr_q <= aw_addr_d;
            w_held_q  <= w_held_d;
            w_data_q  <= w_data_d;
            w_strb_q  <= w_strb_d;
            bvalid_q  <= bvalid_d;
            bresp_q   <= bresp_d;
            rvalid_q  <= rvalid_d;
            rdata_q   <= rdata_d;
            rresp_q   <= rresp_d;
            en_q      <= en_d;
            ie_q      <= ie_d;
            mode_q    <= mode_d;
            expired_q <= expired_d;
            load_q    <= load_d;
            count_q   <= count_d;
        end
    end

`ifdef FORMAL
    // Design-intent assertions (not a proof setup; no .sby submitted here).
    reg f_past_valid;
    initial f_past_valid = 1'b0;
    always @(posedge aclk) f_past_valid <= 1'b1;

    always @(*) begin
        if (!f_past_valid) assume (!aresetn);
    end

    always @(*) begin
        if (f_past_valid) begin
            if (bvalid_q) assert (!aw_held_q && !w_held_q);
            assert (!(aw_held_q && w_held_q));
            assert (irq == (expired_q && ie_q));
        end
    end

    always @(posedge aclk) begin
        if (f_past_valid && $past(!aresetn)) begin
            assert (!bvalid_q);
            assert (!rvalid_q);
            assert (!en_q);
            assert (!expired_q);
            assert (count_q == 32'd0);
        end
    end
`endif

endmodule

`default_nettype wire
=== END FILE ===
