`default_nettype none

// One test lane: one axil_timer instance at ADDR_WIDTH = AW, driven by a
// directed, self-checking sequence. Reports counts to the top.
module axil_timer_tb_lane #(
    parameter integer AW = 4
) (
    input  wire        aclk,
    output reg         done,
    output reg  [31:0] passed,
    output reg  [31:0] failed
);
    localparam integer A_CTRL   = 0;
    localparam integer A_LOAD   = 4;
    localparam integer A_COUNT  = 8;
    localparam integer A_STATUS = 12;
    localparam [1:0]   OKAY     = 2'b00;
    localparam [1:0]   SLVERR   = 2'b10;

    reg          aresetn;
    reg [AW-1:0] awaddr;
    reg          awvalid;
    wire         awready;
    reg [31:0]   wdata;
    reg [3:0]    wstrb;
    reg          wvalid;
    wire         wready;
    wire [1:0]   bresp;
    wire         bvalid;
    reg          bready;
    reg [AW-1:0] araddr;
    reg          arvalid;
    wire         arready;
    wire [31:0]  rdata;
    wire [1:0]   rresp;
    wire         rvalid;
    reg          rready;
    wire         irq;

    axil_timer #(.ADDR_WIDTH(AW)) dut (
        .aclk           (aclk),
        .aresetn        (aresetn),
        .s_axil_awaddr  (awaddr),
        .s_axil_awvalid (awvalid),
        .s_axil_awready (awready),
        .s_axil_wdata   (wdata),
        .s_axil_wstrb   (wstrb),
        .s_axil_wvalid  (wvalid),
        .s_axil_wready  (wready),
        .s_axil_bresp   (bresp),
        .s_axil_bvalid  (bvalid),
        .s_axil_bready  (bready),
        .s_axil_araddr  (araddr),
        .s_axil_arvalid (arvalid),
        .s_axil_arready (arready),
        .s_axil_rdata   (rdata),
        .s_axil_rresp   (rresp),
        .s_axil_rvalid  (rvalid),
        .s_axil_rready  (rready),
        .irq            (irq)
    );

    // Edge counter: after the k-th rising edge, cyc == k.
    reg [31:0] cyc;
    initial cyc = 32'd0;
    always @(posedge aclk) cyc <= cyc + 32'd1;

    // irq rise monitor: irq_rise_edge is the edge after which irq rose.
    reg        irq_last;
    reg [31:0] irq_rise_edge;
    reg [31:0] irq_rises;
    initial begin
        irq_last      = 1'b0;
        irq_rise_edge = 32'd0;
        irq_rises     = 32'd0;
    end
    always @(posedge aclk) begin
        irq_last <= irq;
        if ((irq === 1'b1) && (irq_last === 1'b0)) begin
            irq_rise_edge <= cyc;
            irq_rises     <= irq_rises + 32'd1;
        end
    end

    // Results of the last transfer
    reg [1:0]  wr_resp;
    reg [31:0] wr_edge;
    reg [31:0] rd_data;
    reg [1:0]  rd_resp;
    reg [31:0] rd_edge;

    // Test scratch
    reg [31:0] e;
    reg [31:0] e2;
    reg [31:0] r0;
    reg [31:0] cnt_prev;
    reg [31:0] frozen;
    integer    k;

    // ------------------------------------------------------------------
    // Checking
    // ------------------------------------------------------------------
    task check;
        input         cond;
        input integer tag;
        begin
            if (cond === 1'b1) begin
                passed = passed + 32'd1;
            end else begin
                failed = failed + 32'd1;
                $error("lane AW=%0d: check %0d failed at edge %0d", AW, tag, cyc);
            end
        end
    endtask

    task check_eq;
        input [31:0]  got;
        input [31:0]  exp;
        input integer tag;
        begin
            if (got === exp) begin
                passed = passed + 32'd1;
            end else begin
                failed = failed + 32'd1;
                $error("lane AW=%0d: check %0d failed at edge %0d: got 0x%08h, expected 0x%08h",
                       AW, tag, cyc, got, exp);
            end
        end
    endtask

    task check_resp;
        input [1:0]   got;
        input [1:0]   exp;
        input integer tag;
        begin
            check_eq({30'd0, got}, {30'd0, exp}, tag);
        end
    endtask

    // ------------------------------------------------------------------
    // Timing helpers (all tasks start and end at #1 after a rising edge)
    // ------------------------------------------------------------------
    task idle;
        input integer n;
        integer i;
        begin
            for (i = 0; i < n; i = i + 1) begin
                @(posedge aclk);
                #1;
            end
        end
    endtask

    task wait_edge;
        input [31:0]  t;
        input integer tag;
        begin
            check(cyc <= t, tag);
            while (cyc < t) begin
                @(posedge aclk);
                #1;
            end
        end
    endtask

    task wait_irq;
        input integer limit;
        integer g;
        begin
            g = 0;
            while ((irq !== 1'b1) && (g < limit)) begin
                @(posedge aclk);
                #1;
                g = g + 1;
            end
            check(irq === 1'b1, 9000);
        end
    endtask

    // ------------------------------------------------------------------
    // AXI4-Lite manager tasks
    // ------------------------------------------------------------------
    // order: 0 AW and W together, 1 AW first, 2 W first.
    // bdelay: cycles BREADY is held low after BVALID rises.
    task axi_write;
        input integer a;
        input [31:0]  data;
        input [3:0]   strb;
        input integer order;
        input integer bdelay;
        reg     aw_done;
        reg     w_done;
        reg     aw_fire;
        reg     w_fire;
        integer guard;
        integer i;
        begin
            aw_done = 1'b0;
            w_done  = 1'b0;
            guard   = 0;
            bready  = (bdelay == 0) ? 1'b1 : 1'b0;
            if (order != 2) begin
                awaddr  = a[AW-1:0];
                awvalid = 1'b1;
            end
            if (order != 1) begin
                wdata  = data;
                wstrb  = strb;
                wvalid = 1'b1;
            end
            while (!(aw_done && w_done)) begin
                aw_fire = awvalid && awready;
                w_fire  = wvalid && wready;
                @(posedge aclk);
                #1;
                if (aw_fire) begin
                    awvalid = 1'b0;
                    aw_done = 1'b1;
                end
                if (w_fire) begin
                    wvalid = 1'b0;
                    w_done = 1'b1;
                end
                if ((order == 1) && aw_done && !w_done && !wvalid) begin
                    check(awready === 1'b0, 1000);
                    check(wready === 1'b1, 1001);
                    wdata  = data;
                    wstrb  = strb;
                    wvalid = 1'b1;
                end
                if ((order == 2) && w_done && !aw_done && !awvalid) begin
                    check(wready === 1'b0, 1002);
                    check(awready === 1'b1, 1003);
                    awaddr  = a[AW-1:0];
                    awvalid = 1'b1;
                end
                guard = guard + 1;
                if (guard > 50) begin
                    check(1'b0, 1004);
                    aw_done = 1'b1;
                    w_done  = 1'b1;
                    awvalid = 1'b0;
                    wvalid  = 1'b0;
                end
            end
            check(bvalid === 1'b1, 1005);
            wr_edge = cyc;
            wr_resp = bresp;
            check((awready === 1'b0) && (wready === 1'b0), 1006);
            for (i = 0; i < bdelay; i = i + 1) begin
                @(posedge aclk);
                #1;
                check(bvalid === 1'b1, 1007);
                check(bresp === wr_resp, 1008);
                check((awready === 1'b0) && (wready === 1'b0), 1009);
            end
            bready = 1'b1;
            @(posedge aclk);
            #1;
            check(bvalid === 1'b0, 1010);
            bready = 1'b0;
        end
    endtask

    // rdelay: cycles RREADY is held low after RVALID rises.
    task axi_read;
        input integer a;
        input integer rdelay;
        reg     fire;
        integer guard;
        integer i;
        begin
            araddr  = a[AW-1:0];
            arvalid = 1'b1;
            rready  = (rdelay == 0) ? 1'b1 : 1'b0;
            fire    = 1'b0;
            guard   = 0;
            while (!fire) begin
                fire = arvalid && arready;
                @(posedge aclk);
                #1;
                guard = guard + 1;
                if (guard > 50) begin
                    check(1'b0, 1020);
                    fire = 1'b1;
                end
            end
            arvalid = 1'b0;
            check(rvalid === 1'b1, 1021);
            rd_edge = cyc;
            rd_data = rdata;
            rd_resp = rresp;
            check(arready === 1'b0, 1022);
            for (i = 0; i < rdelay; i = i + 1) begin
                @(posedge aclk);
                #1;
                check(rvalid === 1'b1, 1023);
                check(rdata === rd_data, 1024);
                check(rresp === rd_resp, 1025);
                check(arready === 1'b0, 1026);
            end
            rready = 1'b1;
            @(posedge aclk);
            #1;
            check(rvalid === 1'b0, 1027);
            rready = 1'b0;
        end
    endtask

    task wr;
        input integer a;
        input [31:0]  data;
        input [3:0]   strb;
        input [1:0]   exp_resp;
        input integer tag;
        begin
            axi_write(a, data, strb, 0, 0);
            check_resp(wr_resp, exp_resp, tag);
        end
    endtask

    task rd;
        input integer a;
        input [31:0]  exp_data;
        input [1:0]   exp_resp;
        input integer tag;
        begin
            axi_read(a, 0);
            check_eq(rd_data, exp_data, tag);
            check_resp(rd_resp, exp_resp, tag);
        end
    endtask

    // One-shot count with IE, timed to the cycle; len is the expected
    // number of edges from the starting write to the end of the count.
    task run_oneshot;
        input [31:0]  nload;
        input [31:0]  len;
        input integer tag;
        begin
            wr(A_LOAD, nload, 4'hF, OKAY, tag);
            r0 = irq_rises;
            wr(A_CTRL, 32'h0000_0003, 4'h1, OKAY, tag + 1);
            e = wr_edge;
            if (len >= 32'd4) begin
                axi_read(A_COUNT, 0);
                check_eq(rd_data, nload - (rd_edge - 32'd1 - e), tag + 2);
            end
            wait_irq(len + 10);
            idle(1);
            check_eq(irq_rise_edge, e + len, tag + 3);
            check_eq(irq_rises, r0 + 32'd1, tag + 4);
            rd(A_CTRL, 32'h0000_0002, OKAY, tag + 5);
            rd(A_COUNT, 32'd0, OKAY, tag + 6);
            rd(A_STATUS, 32'd1, OKAY, tag + 7);
            wr(A_STATUS, 32'h0000_0001, 4'h1, OKAY, tag + 8);
            check(irq === 1'b0, tag + 9);
            rd(A_STATUS, 32'd0, OKAY, tag + 10);
            idle(3 * len + 5);
            check_eq(irq_rises, r0 + 32'd1, tag + 11);
            check(irq === 1'b0, tag + 12);
        end
    endtask

    // ------------------------------------------------------------------
    // Directed sequence
    // ------------------------------------------------------------------
    initial begin
        done     = 1'b0;
        passed   = 32'd0;
        failed   = 32'd0;
        aresetn  = 1'b0;
        awaddr   = {AW{1'b0}};
        awvalid  = 1'b0;
        wdata    = 32'd0;
        wstrb    = 4'd0;
        wvalid   = 1'b0;
        bready   = 1'b0;
        araddr   = {AW{1'b0}};
        arvalid  = 1'b0;
        rready   = 1'b0;
        wr_resp  = 2'd0;
        wr_edge  = 32'd0;
        rd_data  = 32'd0;
        rd_resp  = 2'd0;
        rd_edge  = 32'd0;
        e        = 32'd0;
        e2       = 32'd0;
        r0       = 32'd0;
        cnt_prev = 32'd0;
        frozen   = 32'd0;

        repeat (4) @(posedge aclk);
        #1;
        aresetn = 1'b1;
        idle(1);

        // ---- T1: reset values ----
        check(awready === 1'b1, 101);
        check(wready === 1'b1, 102);
        check(arready === 1'b1, 103);
        check(bvalid === 1'b0, 104);
        check(rvalid === 1'b0, 105);
        check(irq === 1'b0, 106);
        rd(A_CTRL,   32'd0, OKAY, 110);
        rd(A_LOAD,   32'd0, OKAY, 111);
        rd(A_COUNT,  32'd0, OKAY, 112);
        rd(A_STATUS, 32'd0, OKAY, 113);

        // ---- T2: LOAD strobes, channel orders, backpressure ----
        axi_write(A_LOAD, 32'hFFFF_FFFF, 4'b1111, 0, 0);
        check_resp(wr_resp, OKAY, 201);
        axi_write(A_LOAD, 32'h1234_5678, 4'b0101, 1, 3);
        check_resp(wr_resp, OKAY, 202);
        axi_read(A_LOAD, 2);
        check_eq(rd_data, 32'hFF34_FF78, 203);
        check_resp(rd_resp, OKAY, 204);
        axi_write(A_LOAD, 32'hA5A5_A5A5, 4'b1010, 2, 2);
        check_resp(wr_resp, OKAY, 205);
        rd(A_LOAD, 32'hA534_A578, OKAY, 206);
        axi_write(A_LOAD, 32'h0000_0000, 4'b0000, 1, 0);
        check_resp(wr_resp, OKAY, 207);
        rd(A_LOAD, 32'hA534_A578, OKAY, 208);
        axi_write(A_LOAD, 32'hDEAD_BEEF, 4'b1111, 2, 1);
        check_resp(wr_resp, OKAY, 209);
        axi_read(A_LOAD, 5);
        check_eq(rd_data, 32'hDEAD_BEEF, 210);
        check_resp(rd_resp, OKAY, 211);

        // ---- T3: SLVERR policy, CTRL without wstrb[0] ----
        wr(A_COUNT, 32'h0000_0055, 4'hF, SLVERR, 301);
        rd(A_COUNT, 32'd0, OKAY, 302);
        wr(5, 32'h0000_0077, 4'hF, SLVERR, 303);
        rd(A_LOAD, 32'hDEAD_BEEF, OKAY, 304);
        wr(1, 32'h0000_0007, 4'hF, SLVERR, 305);
        rd(A_CTRL, 32'd0, OKAY, 306);
        wr(14, 32'h0000_0001, 4'hF, SLVERR, 307);
        rd(2, 32'd0, SLVERR, 308);
        rd(6, 32'd0, SLVERR, 309);
        rd(15, 32'd0, SLVERR, 310);
        if (AW > 4) begin
            wr(16, 32'h0000_0007, 4'hF, SLVERR, 320);
            wr(20, 32'h0000_1234, 4'hF, SLVERR, 321);
            wr(24, 32'h0000_0055, 4'hF, SLVERR, 322);
            wr(28, 32'h0000_0001, 4'hF, SLVERR, 323);
            rd(A_CTRL, 32'd0, OKAY, 324);
            rd(A_LOAD, 32'hDEAD_BEEF, OKAY, 325);
            rd(A_COUNT, 32'd0, OKAY, 326);
            rd(16, 32'd0, SLVERR, 327);
            rd(20, 32'd0, SLVERR, 328);
            rd(28, 32'd0, SLVERR, 329);
            rd(244, 32'd0, SLVERR, 330);
        end
        wr(A_CTRL, 32'h0000_0007, 4'b1110, OKAY, 340);
        rd(A_CTRL, 32'd0, OKAY, 341);
        rd(A_COUNT, 32'd0, OKAY, 342);
        idle(5);
        check(irq === 1'b0, 343);

        // ---- T4: one-shot counts timed to the cycle ----
        run_oneshot(32'd5,  32'd5,  400);
        run_oneshot(32'd1,  32'd1,  420);
        run_oneshot(32'd0,  32'd1,  440);
        run_oneshot(32'd37, 32'd37, 460);

        // ---- T5: interrupt enable on a pending expiry ----
        wr(A_LOAD, 32'd3, 4'hF, OKAY, 501);
        r0 = irq_rises;
        wr(A_CTRL, 32'h0000_0001, 4'h1, OKAY, 502);
        e = wr_edge;
        wait_edge(e + 32'd6, 503);
        check(irq === 1'b0, 504);
        rd(A_STATUS, 32'd1, OKAY, 505);
        rd(A_CTRL, 32'd0, OKAY, 506);
        wr(A_STATUS, 32'h0000_0000, 4'hF, OKAY, 507);
        rd(A_STATUS, 32'd1, OKAY, 508);
        wr(A_STATUS, 32'h0000_0001, 4'b1110, OKAY, 509);
        rd(A_STATUS, 32'd1, OKAY, 510);
        check(irq === 1'b0, 511);
        wr(A_CTRL, 32'h0000_0002, 4'h1, OKAY, 512);
        check(irq === 1'b1, 513);
        check_eq(irq_rise_edge, wr_edge, 514);
        wr(A_CTRL, 32'h0000_0000, 4'h1, OKAY, 515);
        check(irq === 1'b0, 516);
        rd(A_STATUS, 32'd1, OKAY, 517);
        wr(A_CTRL, 32'h0000_0002, 4'h1, OKAY, 518);
        check(irq === 1'b1, 519);
        wr(A_STATUS, 32'h0000_0001, 4'h1, OKAY, 520);
        check(irq === 1'b0, 521);
        rd(A_STATUS, 32'd0, OKAY, 522);
        check_eq(irq_rises, r0 + 32'd2, 523);

        // ---- T6: periodic counts over several periods ----
        wr(A_LOAD, 32'd7, 4'hF, OKAY, 601);
        wr(A_CTRL, 32'h0000_0007, 4'h1, OKAY, 602);
        e = wr_edge;
        for (k = 1; k <= 3; k = k + 1) begin
            wait_irq(20);
            idle(1);
            check_eq(irq_rise_edge, e + 32'd7 * k, 610 + k);
            wr(A_STATUS, 32'h0000_0001, 4'h1, OKAY, 620 + k);
            check(irq === 1'b0, 630 + k);
            axi_read(A_COUNT, 0);
            check_eq(rd_data, 32'd7 - ((rd_edge - 32'd1 - e) % 32'd7), 640 + k);
        end
        // A STATUS clear landing on the edge a count ends: expiry kept
        wait_edge(e + 32'd27, 650);
        wr(A_STATUS, 32'h0000_0001, 4'h1, OKAY, 651);
        check_eq(wr_edge, e + 32'd28, 652);
        check(irq === 1'b1, 653);
        rd(A_STATUS, 32'd1, OKAY, 654);
        wr(A_STATUS, 32'h0000_0001, 4'h1, OKAY, 655);
        check(irq === 1'b0, 656);
        rd(A_CTRL, 32'h0000_0007, OKAY, 657);
        wait_irq(20);
        idle(1);
        check_eq(irq_rise_edge, e + 32'd35, 658);
        wr(A_STATUS, 32'h0000_0001, 4'h1, OKAY, 659);
        check(irq === 1'b0, 660);
        // Stop mid-count: COUNT freezes
        wait_edge(e + 32'd39, 661);
        r0 = irq_rises;
        wr(A_CTRL, 32'h0000_0006, 4'h1, OKAY, 662);
        check_eq(wr_edge, e + 32'd40, 663);
        cnt_prev = 32'd7 - ((wr_edge - 32'd1 - e) % 32'd7);
        frozen   = (cnt_prev <= 32'd1) ? 32'd7 : (cnt_prev - 32'd1);
        rd(A_COUNT, frozen, OKAY, 664);
        rd(A_CTRL, 32'h0000_0006, OKAY, 665);
        idle(30);
        rd(A_COUNT, frozen, OKAY, 666);
        check_eq(irq_rises, r0, 667);
        check(irq === 1'b0, 668);
        rd(A_STATUS, 32'd0, OKAY, 669);
        // EN written 0 on a periodic count end: reload, stop, expiry kept
        wr(A_LOAD, 32'd4, 4'hF, OKAY, 670);
        wr(A_CTRL, 32'h0000_0007, 4'h1, OKAY, 671);
        e = wr_edge;
        wait_edge(e + 32'd3, 672);
        wr(A_CTRL, 32'h0000_0006, 4'h1, OKAY, 673);
        check_eq(wr_edge, e + 32'd4, 674);
        check(irq === 1'b1, 675);
        check_eq(irq_rise_edge, e + 32'd4, 676);
        rd(A_COUNT, 32'd4, OKAY, 677);
        rd(A_CTRL, 32'h0000_0006, OKAY, 678);
        wr(A_STATUS, 32'h0000_0001, 4'h1, OKAY, 679);
        check(irq === 1'b0, 680);
        idle(12);
        rd(A_COUNT, 32'd4, OKAY, 681);
        check(irq === 1'b0, 682);

        // ---- T7: restart, and a stalled read while COUNT moves ----
        wr(A_LOAD, 32'd20, 4'hF, OKAY, 701);
        r0 = irq_rises;
        wr(A_CTRL, 32'h0000_0003, 4'h1, OKAY, 702);
        e = wr_edge;
        idle(5);
        wr(A_CTRL, 32'h0000_0003, 4'h1, OKAY, 703);
        e2 = wr_edge;
        check_eq(e2, e + 32'd7, 704);
        axi_read(A_COUNT, 4);
        check_eq(rd_data, 32'd20 - (rd_edge - 32'd1 - e2), 705);
        check_resp(rd_resp, OKAY, 706);
        wait_irq(40);
        idle(1);
        check_eq(irq_rise_edge, e2 + 32'd20, 707);
        check_eq(irq_rises, r0 + 32'd1, 708);
        wr(A_STATUS, 32'h0000_0001, 4'h1, OKAY, 709);
        check(irq === 1'b0, 710);

        // ---- T8: EN written 1 on a one-shot count end ----
        wr(A_LOAD, 32'd6, 4'hF, OKAY, 801);
        r0 = irq_rises;
        wr(A_CTRL, 32'h0000_0003, 4'h1, OKAY, 802);
        e = wr_edge;
        wait_edge(e + 32'd5, 803);
        wr(A_CTRL, 32'h0000_0003, 4'h1, OKAY, 804);
        check_eq(wr_edge, e + 32'd6, 805);
        check(irq === 1'b1, 806);
        check_eq(irq_rise_edge, e + 32'd6, 807);
        wr(A_STATUS, 32'h0000_0001, 4'h1, OKAY, 808);
        check(irq === 1'b0, 809);
        rd(A_CTRL, 32'h0000_0003, OKAY, 810);
        wait_irq(20);
        idle(1);
        check_eq(irq_rise_edge, e + 32'd12, 811);
        check_eq(irq_rises, r0 + 32'd2, 812);
        rd(A_CTRL, 32'h0000_0002, OKAY, 813);
        wr(A_STATUS, 32'h0000_0001, 4'h1, OKAY, 814);
        check(irq === 1'b0, 815);

        // ---- T9: reset during a count ----
        wr(A_LOAD, 32'd3, 4'hF, OKAY, 901);
        wr(A_CTRL, 32'h0000_0007, 4'h1, OKAY, 902);
        wait_irq(20);
        idle(2);
        aresetn = 1'b0;
        idle(2);
        aresetn = 1'b1;
        idle(1);
        check(irq === 1'b0, 903);
        check(bvalid === 1'b0, 904);
        check(rvalid === 1'b0, 905);
        check(awready === 1'b1, 906);
        check(wready === 1'b1, 907);
        check(arready === 1'b1, 908);
        rd(A_CTRL,   32'd0, OKAY, 910);
        rd(A_LOAD,   32'd0, OKAY, 911);
        rd(A_COUNT,  32'd0, OKAY, 912);
        rd(A_STATUS, 32'd0, OKAY, 913);
        r0 = irq_rises;
        idle(20);
        check_eq(irq_rises, r0, 914);
        check(irq === 1'b0, 915);
        rd(A_COUNT, 32'd0, OKAY, 916);

        done = 1'b1;
    end

endmodule

// Top: runs both lanes, prints the verdict once, ends the simulation.
module axil_timer_tb;
    reg             aclk;
    reg             timeout;
    wire            done4;
    wire            done8;
    wire [31:0]     passed4;
    wire [31:0]     failed4;
    wire [31:0]     passed8;
    wire [31:0]     failed8;
    reg [8*64-1:0]  nonce;
    integer         rc;
    reg [31:0]      passed_total;
    reg [31:0]      failed_total;

    initial aclk = 1'b0;
    always #5 aclk = ~aclk;

    axil_timer_tb_lane #(.AW(4)) lane4 (
        .aclk   (aclk),
        .done   (done4),
        .passed (passed4),
        .failed (failed4)
    );

    axil_timer_tb_lane #(.AW(8)) lane8 (
        .aclk   (aclk),
        .done   (done8),
        .passed (passed8),
        .failed (failed8)
    );

    initial begin
        timeout = 1'b0;
        #1000000;
        timeout = 1'b1;
    end

    initial begin
        nonce = {(8*64){1'b0}};
        rc = $value$plusargs("nirmaan_nonce=%s", nonce);
        wait (((done4 === 1'b1) && (done8 === 1'b1)) || (timeout === 1'b1));
        #1;
        passed_total = passed4 + passed8;
        failed_total = failed4 + failed8;
        if (!((done4 === 1'b1) && (done8 === 1'b1))) begin
            failed_total = failed_total + 32'd1;
            $error("timeout: test lanes did not finish");
        end
        $display("NIRMAAN-SIM %0s %0d passed, %0d failed", nonce, passed_total, failed_total);
        $finish;
    end

endmodule

